19	// decodeAggregateResults parses emitted lines back into AggregateResult so the
20	// assertions observe the exact signed 64-bit start/end/count/sum values.
21	func decodeAggregateResults(t *testing.T, stdout string) []AggregateResult {
22		t.Helper()
23		if stdout == "" {
24			return nil
