48		events := strings.Join([]string{
49			fmt.Sprintf(`{"type":"event","key":"k","time":%d,"value":2}`, M-5),
50			fmt.Sprintf(`{"type":"event","key":"k","time":%d,"value":3}`, M-4),
51		}, "\n")
