83			M-11, M-4, M-7, M)
84		if stdout != want {
85			t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
86		}
87	
88		// Parse the integer fields back: both window bounds must survive as exact
89		// signed 64-bit values with no precision loss or sign flip.
90		got := decodeAggregateResults(t, stdout)
91		wantRows := []AggregateResult{
92			{Key: "k", Start: M - 11, End: M - 4, Count: 1, Sum: 2},
93			{Key: "k", Start: M - 7, End: M, Count: 2, Sum: 5},
94		}
95		if len(got) != len(wantRows) {
96			t.Fatalf("got %d rows, want %d: %v", len(got), len(wantRows), got)
97		}
98		for i := range wantRows {
99			if got[i] != wantRows[i] {
100				t.Errorf("row %d = %+v, want %+v", i, got[i], wantRows[i])
101			}
102		}
103	}
104	
105	// With a window length of math.MaxInt64 and a short slide, events near time
106	// zero belong only to the window starting at zero. No negative-start window
107	// may be generated, and the [0,MaxInt64) window must not be dropped; its end
108	// is exactly MaxInt64 and closes at a watermark equal to it.
109	func TestAggregateSlidingBigWindowLengthNoNegativeStarts(t *testing.T) {
110		const M = math.MaxInt64
111		input := strings.Join([]string{
112			`{"type":"event","key":"k","time":0,"value":5}`,
113			`{"type":"event","key":"k","time":3,"value":7}`,
114			fmt.Sprintf(`{"type":"watermark","time":%d}`, M),
115		}, "\n")
116		stdout, stderr, err := runSliding(t, input, M, 4)
117		if err != nil {
118			t.Fatalf("unexpected error: %v", err)
119		}
120		if stderr != "" {
121			t.Fatalf("unexpected stderr: %q", stderr)
122		}
123		// Exactly one row proves the clamp at start zero: without it, grids such
124		// as [-4,MaxInt64-4) would also contain these events and close here,
125		// producing extra rows and double counting.
126		want := fmt.Sprintf(`{"key":"k","start":0,"end":%d,"count":2,"sum":12}`+"\n", M)
127		if stdout != want {
128			t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
129		}
130		got := decodeAggregateResults(t, stdout)
131		if len(got) != 1 || got[0] != (AggregateResult{Key: "k", Start: 0, End: M, Count: 2, Sum: 12}) {
132			t.Fatalf("decoded rows = %v", got)
133		}
134	}
135	
136	// While the watermark is still below M-3, an event at M-3 (window length 7,
137	// slide 4) falls into both a representable window [M-7,M) and one whose end
138	// overflows [M-3,M+4). The whole input line must fail fatally: the error
139	// carries the physical line number (blank lines still count), says "window
140	// end overflow" and names the earliest offending start M-3. Output already
141	// written stays, the rejected event updates no window, and a later watermark
142	// is never processed.
143	func TestAggregateSlidingBigTimeWindowEndOverflowFatal(t *testing.T) {
144		const M = math.MaxInt64
145		const w, sl int64 = 7, 4
146		input := strings.Join([]string{
147			``, // line 1 blank: physical line numbers still count it
148			fmt.Sprintf(`{"type":"event","key":"k","time":%d,"value":2}`, M-5),
149			fmt.Sprintf(`{"type":"event","key":"k","time":%d,"value":3}`, M-4),
150			fmt.Sprintf(`{"type":"watermark","time":%d}`, M-4), // line 4 closes [M-11,M-4)
151			``, // line 5 blank
152			fmt.Sprintf(`{"type":"event","key":"k","time":%d,"value":9}`, M-3), // line 6 fatal
153			fmt.Sprintf(`{"type":"watermark","time":%d}`, M),                   // line 7 must never be processed
154		}, "\n")
155		stdout, _, err := runSliding(t, input, w, sl)
156		if err == nil {
157			t.Fatal("expected window end overflow error, got nil")
158		}
159		inputErr, ok := err.(*InputError)
160		if !ok {
161			t.Fatalf("expected *InputError, got %T: %v", err, err)
162		}
163		if inputErr.Line != 6 {
164			t.Errorf("line = %d, want 6 (blank lines must count)", inputErr.Line)
165		}
166		if !strings.Contains(inputErr.Reason, "window end overflow") {
167			t.Fatalf("reason = %q, want window end overflow", inputErr.Reason)
168		}
169		wantStart := fmt.Sprintf("window starting at %d with length %d", M-3, w)
170		if !strings.Contains(inputErr.Reason, wantStart) {
171			t.Fatalf("reason = %q, want it to name %s", inputErr.Reason, wantStart)
172		}
173		// The still-fitting window [M-7,M) is not the offender.
174		if strings.Contains(inputErr.Reason, fmt.Sprintf("starting at %d", M-7)) {
175			t.Errorf("reason must not blame the fitting window start %d: %q", M-7, inputErr.Reason)
176		}
177		// Prior output is retained exactly; the post-error watermark never runs,
178		// so [M-7,M) must not appear even though M would close it.
179		want := fmt.Sprintf(`{"key":"k","start":%d,"end":%d,"count":1,"sum":2}`+"\n", M-11, M-4)
180		if stdout != want {
181			t.Fatalf("existing output must be retained with nothing added:\n got: %q\nwant: %q", stdout, want)
182		}
183	}
184	
185	// At the big boundary, slide equal to the window length must stay exactly
186	// identical to RunAggregate's fixed-window behavior: a legal end at
187	// math.MaxInt64 succeeds through both entry points, and a window end past
188	// math.MaxInt64 is rejected with the same error from both.
189	func TestAggregateSlidingBigTimeEqualsFixedWindow(t *testing.T) {
190		const M = math.MaxInt64
191	
192		okInput := strings.Join([]string{
193			`{"type":"event","key":"k","time":0,"value":11}`,
194			fmt.Sprintf(`{"type":"watermark","time":%d}`, M),
195		}, "\n")
196		slidingOut, _, err := runSliding(t, okInput, M, M)
197		if err != nil {
198			t.Fatalf("sliding: unexpected error: %v", err)
199		}
200		var fixedOut bytes.Buffer
201		if err := RunAggregate(strings.NewReader(okInput), M, &fixedOut, &bytes.Buffer{}); err != nil {
202			t.Fatalf("fixed: unexpected error: %v", err)
203		}
204		if slidingOut != fixedOut.String() {
205			t.Fatalf("slide==window output %q != fixed output %q", slidingOut, fixedOut.String())
206		}
207		want := fmt.Sprintf(`{"key":"k","start":0,"end":%d,"count":1,"sum":11}`+"\n", M)
208		if slidingOut != want {
209			t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", slidingOut, want)
210		}
211	
212		// Window length 7 (M is divisible by 7): time M belongs to the fixed
213		// window [M,M+7), whose end overflows. Both entry points must report the
214		// same fatal line and offending start.
215		badInput := fmt.Sprintf(`{"type":"event","key":"k","time":%d,"value":1}`+"\n", M)
216		_, _, slidingErr := runSliding(t, badInput, 7, 7)
217		fixedErr := RunAggregate(strings.NewReader(badInput), 7, &bytes.Buffer{}, &bytes.Buffer{})
218		if slidingErr == nil || fixedErr == nil {
219			t.Fatalf("expected overflow from sliding=%v fixed=%v", slidingErr, fixedErr)
220		}
221		if slidingErr.Error() != fixedErr.Error() {
222			t.Fatalf("sliding error %q != fixed error %q", slidingErr, fixedErr)
223		}
224		if !strings.Contains(slidingErr.Error(), "window end overflow") {
225			t.Fatalf("error = %q, want window end overflow", slidingErr.Error())
226		}
227		if !strings.Contains(slidingErr.Error(), fmt.Sprintf("starting at %d", M)) {
228			t.Fatalf("error = %q, want offending start %d", slidingErr.Error(), M)
229		}
230	}
