10	// Regression safeguards for the cumulative sum of sliding windows at the
11	// signed 64-bit value boundaries. Each containing window keeps its own
12	// independent sum: a valid event's full value is added to every window that
13	// contains it (never split across the overlap), sums landing exactly on
14	// math.MaxInt64 or math.MinInt64 are legal and keep full integer precision
15	// in the JSON output, and only an addition that would cross a boundary is
16	// fatal — at the input line that triggers it, naming the window that truly
17	// overflows. Scope is the legacy single-watermark RunAggregateSliding entry
18	// point.
19	
20	// The full value lands in every containing window; nothing is divided across
21	// the overlap. With window 1000, slide 600 the event at 700 belongs to
22	// [0,1000) and [600,1600), the event at 1200 to [600,1600) and [1200,2200),
23	// so each window's sum reflects exactly its own event set.
24	func TestAggregateSlidingSumFullValueEachWindow(t *testing.T) {
25		input := strings.Join([]string{
26			`{"type":"event","key":"k","time":700,"value":7}`,
27			`{"type":"event","key":"k","time":1200,"value":11}`,
28			`{"type":"watermark","time":2200}`,
29		}, "\n")
30		stdout, stderr, err := runSliding(t, input, 1000, 600)
31		if err != nil {
32			t.Fatalf("unexpected error: %v", err)
33		}
34		if stderr != "" {
35			t.Fatalf("unexpected stderr: %q", stderr)
36		}
37		want := strings.Join([]string{
38			`{"key":"k","start":0,"end":1000,"count":1,"sum":7}`,     // 700 only
39			`{"key":"k","start":600,"end":1600,"count":2,"sum":18}`,  // 700 and 1200
40			`{"key":"k","start":1200,"end":2200,"count":1,"sum":11}`, // 1200 only
41			``,
42		}, "\n")
43		if stdout != want {
44			t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
45		}
46	}
