79			{Key: "lo", Start: 0, End: 1000, Count: 2, Sum: math.MinInt64},
80		}
81		if len(got) != len(wantRows) {
82			t.Fatalf("got %d rows, want %d: %v", len(got), len(wantRows), got)
83		}
84		for i := range wantRows {
85			if got[i] != wantRows[i] {
86				t.Errorf("row %d = %+v, want %+v", i, got[i], wantRows[i])
87			}
88		}
89	}
90	
91	// Legal values above 2^53 must not lose precision: 2^53+1 is not exactly
92	// representable as a float64, so any float round-trip in the sum path would
93	// print 9007199254740992 and 18014398509481984 instead of the true values.
94	func TestAggregateSlidingSumPrecisionAbove2To53(t *testing.T) {
95		input := strings.Join([]string{
96			`{"type":"event","key":"k","time":100,"value":9007199254740993}`, // 2^53+1
97			`{"type":"event","key":"k","time":700,"value":9007199254740993}`, // shared by both windows
98			`{"type":"watermark","time":1600}`,
99		}, "\n")
100		stdout, stderr, err := runSliding(t, input, 1000, 600)
101		if err != nil {
102			t.Fatalf("unexpected error: %v", err)
103		}
104		if stderr != "" {
105			t.Fatalf("unexpected stderr: %q", stderr)
106		}
107		want := strings.Join([]string{
108			`{"key":"k","start":0,"end":1000,"count":2,"sum":18014398509481986}`, // 2*(2^53+1)
109			`{"key":"k","start":600,"end":1600,"count":1,"sum":9007199254740993}`,
110			``,
111		}, "\n")
112		if stdout != want {
113			t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
114		}
115	}
116	
117	// The same legal boundary sum can coexist in overlapping windows with
118	// different event sets: the event at 999 (value MaxInt64) belongs to both
119	// [0,1000) and [600,1600), while the event at 1000 (value -1) joins only
120	// [600,1600). Both windows close with their own exact sums.
121	func TestAggregateSlidingSumBoundarySharedAcrossOverlap(t *testing.T) {
122		input := strings.Join([]string{
123			`{"type":"event","key":"k","time":999,"value":9223372036854775807}`,
124			`{"type":"event","key":"k","time":1000,"value":-1}`,
125			`{"type":"watermark","time":1600}`,
126		}, "\n")
127		stdout, stderr, err := runSliding(t, input, 1000, 600)
128		if err != nil {
129			t.Fatalf("unexpected error: %v", err)
130		}
131		if stderr != "" {
132			t.Fatalf("unexpected stderr: %q", stderr)
133		}
134		want := strings.Join([]string{
135			`{"key":"k","start":0,"end":1000,"count":1,"sum":9223372036854775807}`,
136			`{"key":"k","start":600,"end":1600,"count":2,"sum":9223372036854775806}`,
137			``,
138		}, "\n")
139		if stdout != want {
140			t.Fatalf("stdout mismatch:\n got: %q\nwant: %q", stdout, want)
141		}
142	}
143	
144	// Positive and negative values may cancel inside a window; the count keeps
145	// tracking the actually accepted events, and a non-empty window whose sum
146	// returned to zero is still emitted — it is not an empty window. Key "edge"
147	// cancels through the full signed range (MaxInt64 + MinInt64 + 1 = 0).
148	func TestAggregateSlidingSumCancellationKeepsCount(t *testing.T) {
149		input := strings.Join([]string{
150			`{"type":"event","key":"k","time":700,"value":5}`,
151			`{"type":"event","key":"k","time":800,"value":-5}`,
