302	// A cumulative sum overflow reached through overlapping windows is fatal for
303	// that input line and names the offending window.
304	func TestAggregateSlidingSumOverflow(t *testing.T) {
305		input := strings.Join([]string{
306			`{"type":"event","key":"k","time":700,"value":9223372036854775807}`,
307			`{"type":"event","key":"k","time":800,"value":1}`, // adds to both windows covering 700..800
308		}, "\n")
309		_, _, err := runSliding(t, input, 1000, 600)
310		if err == nil {
311			t.Fatal("expected cumulative sum overflow")
312		}
313		inputErr, ok := err.(*InputError)
314		if !ok {
315			t.Fatalf("expected *InputError, got %T: %v", err, err)
316		}
317		if inputErr.Line != 2 {
318			t.Errorf("line = %d, want 2", inputErr.Line)
319		}
320		if !strings.Contains(inputErr.Reason, "sum overflow") {
321			t.Fatalf("reason = %q, want sum overflow", inputErr.Reason)
322		}
323		if !strings.Contains(inputErr.Reason, "[0,1000)") {
324			t.Fatalf("overflow should name the offending window [0,1000), got %q", inputErr.Reason)
325		}
326	}
327	
328	// Overflow in a later containing window must not leave earlier windows of the
329	// same line partially updated: the failing event counts in no window.
330	func TestAggregateSlidingOverflowLeavesNoPartialUpdate(t *testing.T) {
331		// First event lands in [0,1000) and [600,1600); second positive overflow
332		// event is rejected, so a later watermark still shows count 1.
333		input := strings.Join([]string{
334			`{"type":"event","key":"k","time":700,"value":1}`,
335			`{"type":"event","key":"k","time":800,"value":9223372036854775807}`,
336			`{"type":"watermark","time":1600}`,
337		}, "\n")
338		stdout, _, err := runSliding(t, input, 1000, 600)
339		if err == nil {
340			t.Fatal("expected overflow error")
341		}
342		// Nothing closes before the fatal line, so no window should carry the
343		// rejected event; output is empty because the only watermark runs after
344		// the failure and is never reached.
345		if stdout != "" {
346			t.Fatalf("failing line must not update any window, got %q", stdout)
347		}
348	}
