33	// seedCountWindow prepares one key/window pair already holding count events
34	// and the given sum, marking its end so watermark closure works unchanged.
35	func seedCountWindow(s *aggregateState, key string, start, end, count, sum int64) {
36		s.windows[windowID{start: start, key: key}] = &windowState{end: end, count: count, sum: sum}
37	}
38	
39	// runSlidingState feeds input to an already seeded state through the normal
40	// line collector, so seeding never bypasses physical line counting or any
41	// record check. It returns the captured window output and late-event output.
42	func runSlidingState(s *aggregateState, input string) (string, string, error) {
43		var stdout, stderr bytes.Buffer
44		s.out = &stdout
45		s.lateLog = &stderr
46		err := readAggregateLines(strings.NewReader(input), func(line string, no int) error {
47			if strings.TrimSpace(line) == "" {
48				return nil
49			}
50			return s.processLine(line, no)
51		})
52		return stdout.String(), stderr.String(), err
53	}
54	
55	// newCountState builds a legacy single-watermark sliding state with the given
56	// window length and slide interval and an empty window map.
57	func newCountState(windowMillis, slideMillis int64) *aggregateState {
58		return &aggregateState{
59			windowMillis: windowMillis,
60			slideMillis:  slideMillis,
61			windows:      make(map[windowID]*windowState),
62		}
63	}
