117	// Once a window already holds math.MaxInt64 events, the next event that should
118	// otherwise be accepted fails on that line even when its value is zero and
119	// could not overflow the sum. The *InputError reports "event count overflow"
120	// with the physical line number (blank lines count), the key and the window's
121	// [start,end) interval. Records after the failure are not read, open windows
122	// are not replayed, and the result fully written before it stays as is.
123	func TestAggregateSlidingCountOverflowFatalWithZeroValue(t *testing.T) {
124		const M = math.MaxInt64
125		s := newCountState(1000, 600)
126		// A window that closes and is written before the failing record.
