168	// The count is incremented for every accepted value sign: a negative-valued
169	// event at count M-1 still lands exactly on M (sum moves independently), and
170	// the following zero-valued event is then rejected as a count overflow --
171	// value zero can never masquerade as "no event".
172	func TestAggregateSlidingCountIncrementedForNegativeAndZeroValues(t *testing.T) {
173		const M = math.MaxInt64
174		s := newCountState(1000, 600)
175		seedCountWindow(s, "sensor-a", 600, 1600, M-1, 41)
176	
